for k,(rows,score) in T.items():
    present=sum(r[0] for r in rows if r[1] is not None); f=100/present
    bad=[]; tot=0
    for base,b,mx,pts in rows:
        if b is None: continue
        exp=base*f*(0.5+0.5*b)
        if abs(exp-pts)>0.03 or abs(base*f-mx)>0.03: bad.append((base,b,round(exp,2),pts))
